import math

def ncdf(z):
    return 0.5 * math.erfc(-z / math.sqrt(2))

mu, sigma = 50, 12
for n in (9, 36, 144):
    se = sigma / math.sqrt(n)
    print(n, se, round(1 - ncdf((53 - mu) / se), 4))

import math

def ncdf(z):
    return 0.5 * math.erfc(-z / math.sqrt(2))

se = 2.0
crit = 100 + 1.645 * se
print(round(crit, 3))
for mu in (100, 102, 104, 106):
    power = 1 - ncdf((crit - mu) / se)
    print(mu, round(power, 4))
